import gurobipy as gp
from gurobipy import GRB

# Create the model
model = gp.Model("SteelPipeCutting")

# Define the decision variables
x = {}
y = {}
for i in range(1, data["max_cutting_patterns"] + 1):
    y[i] = model.addVar(vtype=GRB.INTEGER, name=f"y_{i}")
    for j in data["order_requirements"]:
        x[(i, j)] = model.addVar(vtype=GRB.INTEGER, name=f"x_{i}_{j}")

# Set the objective function
total_cost = gp.quicksum(data["raw_pipe_length"] * y[i] + data["extra_cost_coefficients"][i-1] * y[i] 
                         for i in range(1, data["max_cutting_patterns"] + 1))
model.setObjective(total_cost, GRB.MINIMIZE)

# Add the constraints
# Demand satisfaction
for j in data["order_requirements"]:
    model.addConstr(gp.quicksum(x[(i, j)] for i in range(1, data["max_cutting_patterns"] + 1)) >= data["order_requirements"][j], 
                    f"demand_{j}")

# Maximum pieces per raw pipe
for i in range(1, data["max_cutting_patterns"] + 1):
    model.addConstr(gp.quicksum(x[(i, j)] for j in data["order_requirements"]) <= data["max_pieces_per_raw_pipe"], 
                    f"max_pieces_{i}")

# Leftover length constraint
for i in range(1, data["max_cutting_patterns"] + 1):
    model.addConstr(data["raw_pipe_length"] - gp.quicksum(x[(i, j)] * int(j.split('_')[0]) for j in data["order_requirements"]) <= data["max_leftover_length"], 
                    f"leftover_{i}")

# Optimize the model
model.optimize()

# Check if the model has an optimal solution
if model.status == GRB.OPTIMAL:
    print(f"Optimal solution found with total cost: {model.ObjVal}")
    # Output the cutting plan
    for i in range(1, data["max_cutting_patterns"] + 1):
        if y[i].X > 0:
            print(f"Cutting Pattern {i}:")
            for j in data["order_requirements"]:
                if x[(i, j)].X > 0:
                    print(f"  {x[(i, j)].X} pieces of {j}")
else:
    print("No optimal solution found.")
